mapper.delete:
DELETE FROM notice_files nf
WHERE nf.notice_id = #{notice_id}
  AND nf.notice_file_id = #{notice_file_id}
  AND EXISTS (
      SELECT 1
      FROM notice n
      WHERE n.notice_id = nf.notice_id
        AND n.deleted IS NULL

  )
